// GENERATED by assembly/routes.ts on every build — never edited. Where each book of the library stands.
import { $$Book, type $Book } from '@dna-platform/public';
import { books } from './books';

export type Route = { name: string; folder: string; address: string; load: () => Promise<{ book: $Book }> };

export const routes: Route[] = [
    { name: "Doug’s Library", folder: "..reference", address: "/", load: books["..reference"] },
    { name: "Claude & Our Projects", folder: ".claude-and-our-projects/.reference", address: "/claude-and-our-projects", load: books[".claude-and-our-projects/.reference"] },
    { name: "Semantic Reference Theory", folder: ".claude-and-our-projects/semantic-reference-theory/.reference", address: "/semantic-reference-theory", load: books[".claude-and-our-projects/semantic-reference-theory/.reference"] },
    { name: "Semantics of Types & More", folder: ".claude-and-our-projects/semantic-reference-theory/conversations/semantics-of-types", address: "/semantics-of-types-and-more", load: books[".claude-and-our-projects/semantic-reference-theory/conversations/semantics-of-types"] },
    { name: "MY Library Log", folder: "my-library-log", address: "/my-library-log", load: books["my-library-log"] },
];

export const root: Route | undefined = routes[0];

// THE LIBRARY IS CONNECTED HERE, BEFORE ANY BOOK IS OPENED. Every page that loads this table
// has the shelf up, which is what makes a mention of a book lead to that book.
const base = import.meta.env.BASE_URL.replace(/\/$/, '');
$$Book.shelve(routes.map(route => ({ name: route.name, address: `${base}${route.address}${route.address.endsWith('/') ? '' : '/'}` })));
